from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7600"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8500"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj += Decimal("0.0100") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor <= MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)

axle_weights.py:
"""Federal axle weight checks for a loaded tractor-trailer (23 CFR 658.17).

Load planning runs ``check_axle_weights`` on the scale ticket or the planned axle
loads before a truck is dispatched onto the Interstate. The federal limits:

- 20,000 lbs on any single axle.
- 34,000 lbs on a tandem (two axles more than 40" and at most 96" apart).
- 80,000 lbs gross.
- The bridge formula, W = 500 * (L*N/(N-1) + 12*N + 36), on every group of two or
  more consecutive axles: N is the number of axles in the group, L the distance
  in feet between its outer axles, W the most the group may carry. Like the
  published bridge table, W is rounded to the nearest 500 lbs. A group that is
  just one tandem is covered by the tandem limit instead.
- Exception: two consecutive tandems may carry 34,000 lbs each (68,000 together)
  if their outer axles are 36 feet or more apart, even when the formula gives
  less.

Axles are given front to back, with positions in feet from the steer axle.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

SINGLE_LIMIT = 20_000
TANDEM_LIMIT = 34_000
GROSS_LIMIT = 80_000
TANDEM_MAX_SPACING_FT = 8.0
DOUBLE_TANDEM_MIN_SPAN_FT = 36.0
DOUBLE_TANDEM_LIMIT = 68_000


@dataclass(frozen=True)
class Violation:
    rule: str  # "single", "tandem", "gross" or "bridge"
    first_axle: int
    last_axle: int
    weight: int
    limit: int


def bridge_limit(span_ft: float, axles: int) -> int:
    """The bridge formula for ``axles`` axles spread over ``span_ft`` feet."""
    if axles < 2:
        raise ValueError("the bridge formula needs at least two axles")
    raw = 500 * (Decimal(str(span_ft)) * axles / (axles - 1) + 12 * axles + 36)
    return int((raw / 500).quantize(Decimal(1), rounding=ROUND_HALF_UP) * 500)


def _tandem_starts(positions: list[float]) -> set[int]:
    """Indexes of axles that are the front axle of a tandem."""
    return {
        i for i in range(len(positions) - 1)
        if positions[i + 1] - positions[i] <= TANDEM_MAX_SPACING_FT
    }


def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles, except lone tandems."""
    return [
        (first, last)
        for first in range(axle_count)
        for last in range(first + 1, axle_count)
        if not (last == first + 1 and first in tandems)
    ]


def _span_limit(first: int, last: int, positions: list[float], tandems: set[int]) -> int:
    span = positions[last] - positions[first]
    limit = bridge_limit(span, last + first + 1)
    double_tandem = last - first == 3 and first in tandems and first + 2 in tandems
    if double_tandem and span >= DOUBLE_TANDEM_MIN_SPAN_FT:
        limit = max(limit, DOUBLE_TANDEM_LIMIT)
    return limit


def check_axle_weights(weights: list[int], positions: list[float]) -> list[Violation]:
    """Every federal limit the axle loads break; an empty list means legal."""
    if len(weights) != len(positions) or len(weights) < 2:
        raise ValueError("need a weight and a position for each of at least two axles")
    if any(b <= a for a, b in zip(positions, positions[1:])):
        raise ValueError("axle positions must increase front to back")
    tandems = _tandem_starts(positions)
    in_tandem = tandems | {i + 1 for i in tandems}
    violations = []
    for i, weight in enumerate(weights):
        if i not in in_tandem and weight > SINGLE_LIMIT:
            violations.append(Violation("single", i, i, weight, SINGLE_LIMIT))
    for i in sorted(tandems):
        weight = weights[i] + weights[i + 1]
        if weight > TANDEM_LIMIT:
            violations.append(Violation("tandem", i, i + 1, weight, TANDEM_LIMIT))
    gross = sum(weights)
    if gross > GROSS_LIMIT:
        violations.append(Violation("gross", 0, len(weights) - 1, gross, GROSS_LIMIT))
    for first, last in _bridge_spans(len(weights), tandems):
        weight = sum(weights[first:last + 1])
        limit = _span_limit(first, last, positions, tandems)
        if weight > limit:
            violations.append(Violation("bridge", first, last, weight, limit))
    return violations

lane_rates.py:
"""Contract lane rate lookup with fallbacks.

Customer contracts price linehaul per mile by lane. Pricing loads them at three
levels of detail, most specific first:

    zip3        origin ZIP3 -> destination ZIP3   ("972" -> "837")
    zip3_state  origin ZIP3 -> destination state  ("972" -> "ID")
    state       origin state -> destination state ("OR" -> "ID")

Every rate has an effective date and an optional expiry date (inclusive). Rates
get renegotiated lane by lane, so the specific lanes often lapse before the
state-level rates do. A lookup uses the most specific level that has a rate in
effect on the ship date, and falls back to the customer's default per-mile rate
when no level does. If two rates at one level are in effect at once, the one with
the later effective date wins: it is the newer contract amendment.
"""

from dataclasses import dataclass
from datetime import date
from decimal import ROUND_HALF_UP, Decimal

LEVELS = ("zip3", "zip3_state", "state")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class LaneRate:
    level: str
    origin: str
    dest: str
    rate_per_mile: Decimal
    effective: date
    expires: date | None = None


@dataclass(frozen=True)
class Shipment:
    origin_zip: str
    origin_state: str
    dest_zip: str
    dest_state: str
    ship_date: date


@dataclass(frozen=True)
class RateMatch:
    rate_per_mile: Decimal
    level: str


RateTable = dict[tuple[str, str, str], list[LaneRate]]


def build_rate_table(rates: list[LaneRate]) -> RateTable:
    table: RateTable = {}
    for rate in rates:
        if rate.level not in LEVELS:
            raise ValueError(f"unknown lane level {rate.level!r}")
        table.setdefault((rate.level, rate.origin, rate.dest), []).append(rate)
    return table


def _candidate_keys(shipment: Shipment) -> list[tuple[str, str, str]]:
    origin3, dest3 = shipment.origin_zip[:3], shipment.dest_zip[:3]
    return [
        ("zip3", origin3, dest3),
        ("zip3_state", origin3, shipment.dest_state),
        ("state", shipment.origin_state, shipment.dest_state),
    ]


def _in_effect(rates: list[LaneRate], on: date) -> list[LaneRate]:
    return [r for r in rates if r.effective <= on and (r.expires is None or on <= r.expires)]


def _most_specific(table: RateTable, shipment: Shipment) -> tuple[str | None, list[LaneRate]]:
    """The most specific level with a rate in effect on the ship date, and those rates."""
    for key in _candidate_keys(shipment):
        live = _in_effect(table.get(key, []), shipment.ship_date)
        if live:
            return key[0], live
    return None, []


def lookup_lane_rate(
    table: RateTable, shipment: Shipment, default_rate: Decimal | None = None
) -> RateMatch:
    """The per-mile rate for ``shipment``, and which level it came from.

    Raises LookupError if no lane rate applies and the customer has no default.
    """
    level, live = _most_specific(table, shipment)
    if live:
        newest = min(live, key=lambda rate: rate.effective)
        return RateMatch(newest.rate_per_mile, level)
    if default_rate is None:
        raise LookupError(f"no lane rate for {shipment.origin_zip} -> {shipment.dest_zip}")
    return RateMatch(default_rate, "default")


def linehaul(table: RateTable, shipment: Shipment, miles: Decimal, default_rate: Decimal | None = None) -> Decimal:
    """Linehaul dollars for the shipment's miles, rounded to the cent."""
    rate = lookup_lane_rate(table, shipment, default_rate).rate_per_mile
    return (rate * miles).quantize(CENT, rounding=ROUND_HALF_UP)

